#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Runa disk-watchdog: Disk usage monitoring and automatic purge for A2A Mesh.

- Monitors disk usage on the partition hosting the repo.
- Automatic purge of old logs and WAL archives when usage exceeds 85%.
- Target: keep disk usage below 85%.
- Alert (stderr + optional webhook) when usage reaches 90%.
- Integrates with A2A Mesh idea-láda (idea_f505d779d234).

Usage:
    python3 runa_disk_watchdog.py                  # single check
    python3 runa_disk_watchdog.py --daemon         # continuous monitoring
    python3 runa_disk_watchdog.py --dry-run        # show what would be purged
    python3 runa_disk_watchdog.py --status         # print JSON status
"""

import argparse
import json
import logging
import os
import shutil
import sys
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

REPO_ROOT = Path(__file__).resolve().parent

# Directories to scan for purge candidates
LOG_DIRS = [
    REPO_ROOT / "logs",
    REPO_ROOT / "var" / "logs",
    REPO_ROOT / "data" / "logs",
]

WAL_ARCHIVE_DIRS = [
    REPO_ROOT / "data" / "pg_wal" / "archive",
    REPO_ROOT / "var" / "pg_wal" / "archive",
    REPO_ROOT / "wal_archive",
]

# Thresholds (percent)
PURGE_THRESHOLD = 85.0
ALERT_THRESHOLD = 90.0
TARGET_THRESHOLD = 80.0  # purge until below this

# Retention
LOG_RETENTION_DAYS = 14
WAL_RETENTION_DAYS = 7
WAL_RETENTION_COUNT = 200  # keep at least N most recent WAL segments

# Polling interval for daemon mode (seconds)
DAEMON_INTERVAL = 300  # 5 minutes

# State file for tracking last alert / purge
STATE_FILE = REPO_ROOT / "var" / "runa_disk_watchdog_state.json"

# Webhook URL (optional, read from env)
WEBHOOK_URL = os.environ.get("RUNA_DISK_WEBHOOK_URL", "")

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------

LOG_FORMAT = "%(asctime)s [%(levelname)s] runa-disk-watchdog: %(message)s"
logging.basicConfig(level=logging.INFO, format=LOG_FORMAT, stream=sys.stderr)
log = logging.getLogger("runa.disk_watchdog")


# ---------------------------------------------------------------------------
# Disk usage
# ---------------------------------------------------------------------------

def get_disk_usage(path: Path) -> tuple[float, float, float]:
    """Return (total_bytes, used_bytes, free_bytes) for the partition holding path."""
    usage = shutil.disk_usage(str(path))
    return usage.total, usage.used, usage.free


def get_disk_percent(path: Path) -> float:
    total, used, _ = get_disk_usage(path)
    if total == 0:
        return 0.0
    return (used / total) * 100.0


# ---------------------------------------------------------------------------
# Purge helpers
# ---------------------------------------------------------------------------

def find_old_logs(retention_days: int) -> list[Path]:
    """Find log files older than retention_days."""
    cutoff = datetime.now(timezone.utc) - timedelta(days=retention_days)
    candidates: list[tuple[float, Path]] = []

    for log_dir in LOG_DIRS:
        if not log_dir.exists():
            continue
        for entry in log_dir.rglob("*"):
            if not entry.is_file():
                continue
            try:
                mtime = datetime.fromtimestamp(entry.stat().st_mtime, tz=timezone.utc)
            except OSError:
                continue
            if mtime < cutoff:
                candidates.append((entry.stat().st_mtime, entry))

    candidates.sort(key=lambda x: x[0])  # oldest first
    return [p for _, p in candidates]


def find_old_wal(retention_days: int, min_keep: int) -> list[Path]:
    """Find WAL archive files to purge, keeping at least min_keep most recent."""
    cutoff = datetime.now(timezone.utc) - timedelta(days=retention_days)
    all_wal: list[tuple[float, Path]] = []

    for wal_dir in WAL_ARCHIVE_DIRS:
        if not wal_dir.exists():
            continue
        for entry in wal_dir.rglob("*"):
            if not entry.is_file():
                continue
            # WAL segment files are typically 24 hex chars, .gz, .partial, etc.
            try:
                mtime = entry.stat().st_mtime
            except OSError:
                continue
            all_wal.append((mtime, entry))

    all_wal.sort(key=lambda x: x[0], reverse=True)  # newest first

    # Keep at least min_keep most recent
    to_keep = set()
    for i, (mtime, p) in enumerate(all_wal):
        if i < min_keep:
            to_keep.add(p)
        else:
            dt = datetime.fromtimestamp(mtime, tz=timezone.utc)
            if dt >= cutoff:
                to_keep.add(p)

    purge_list = [p for _, p in all_wal if p not in to_keep]
    # Sort oldest first for purging
    purge_list.sort(key=lambda p: p.stat().st_mtime if p.exists() else 0)
    return purge_list


def purge_files(files: list[Path], dry_run: bool = False) -> tuple[int, int]:
    """Delete files. Returns (count_purged, bytes_freed)."""
    count = 0
    freed = 0
    for f in files:
        if not f.exists():
            continue
        try:
            size = f.stat().st_size
        except OSError:
            size = 0
        if dry_run:
            log.info("[dry-run] would delete %s (%d bytes)", f, size)
            count += 1
            freed += size
            continue
        try:
            f.unlink()
            count += 1
            freed += size
            log.debug("purged %s (%d bytes)", f, size)
        except OSError as e:
            log.warning("failed to purge %s: %s", f, e)
    return count, freed


def cleanup_empty_dirs():
    """Remove empty directories under log/wal dirs after purge."""
    for dirs in (LOG_DIRS, WAL_ARCHIVE_DIRS):
        for d in dirs:
            if not d.exists():
                continue
            for sub in sorted(d.rglob("*"), reverse=True):
                if sub.is_dir():
                    try:
                        sub.rmdir()
                    except OSError:
                        pass  # not empty


# ---------------------------------------------------------------------------
# State management
# ---------------------------------------------------------------------------

def load_state() -> dict:
    if STATE_FILE.exists():
        try:
            return json.loads(STATE_FILE.read_text())
        except (json.JSONDecodeError, OSError):
            pass
    return {}


def save_state(state: dict):
    STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    STATE_FILE.write_text(json.dumps(state, indent=2, default=str))


# ---------------------------------------------------------------------------
# Alerting
# ---------------------------------------------------------------------------

def send_alert(percent: float, message: str):
    """Send alert to stderr and optionally to webhook."""
    log.error("ALERT: disk usage %.1f%% — %s", percent, message)

    if WEBHOOK_URL:
        try:
            import urllib.request
            payload = json.dumps({
                "agent": "runa",
                "component": "disk-watchdog",
                "severity": "critical",
                "disk_percent": round(percent, 1),
                "message": message,
                "timestamp": datetime.now(timezone.utc).isoformat(),
            }).encode()
            req = urllib.request.Request(
                WEBHOOK_URL,
                data=payload,
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            urllib.request.urlopen(req, timeout=10)
        except Exception as e:
            log.warning("webhook alert failed: %s", e)


# ---------------------------------------------------------------------------
# Core watchdog logic
# ---------------------------------------------------------------------------

def run_watchdog(dry_run: bool = False) -> dict:
    """Run a single watchdog cycle. Returns a status dict."""
    total, used, free = get_disk_usage(REPO_ROOT)
    percent = (used / total * 100.0) if total > 0 else 0.0

    status = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "partition": str(REPO_ROOT),
        "total_bytes": total,
        "used_bytes": used,
        "free_bytes": free,
        "disk_percent": round(percent, 2),
        "purge_threshold": PURGE_THRESHOLD,
        "alert_threshold": ALERT_THRESHOLD,
        "purged_files": 0,
        "purged_bytes": 0,
        "action": "none",
    }

    log.info("disk usage: %.1f%% (used=%d, free=%d, total=%d)",
             percent, used, free, total)

    # Alert at 90%
    if percent >= ALERT_THRESHOLD:
        send_alert(percent, f"Disk usage {percent:.1f}% exceeds alert threshold {ALERT_THRESHOLD}%")
        status["action"] = "alert"

    # Purge at 85%
    if percent >= PURGE_THRESHOLD:
        log.warning("disk usage %.1f%% >= purge threshold %.1f%% — starting purge",
                    percent, PURGE_THRESHOLD)
        status["action"] = "purging"

        total_purged_files = 0
        total_purged_bytes = 0

        # Phase 1: purge old logs
        old_logs = find_old_logs(LOG_RETENTION_DAYS)
        if old_logs:
            log.info("found %d old log files (>%d days) to purge", len(old_logs), LOG_RETENTION_DAYS)
            n, b = purge_files(old_logs, dry_run=dry_run)
            total_purged_files += n
            total_purged_bytes += b

        # Check if we've dropped below target
        current_percent = get_disk_percent(REPO_ROOT)
        if current_percent >= TARGET_THRESHOLD:
            # Phase 2: purge old WAL archives
            old_wal = find_old_wal(WAL_RETENTION_DAYS, WAL_RETENTION_COUNT)
            if old_wal:
                log.info("found %d old WAL segments to purge", len(old_wal))
                n, b = purge_files(old_wal, dry_run=dry_run)
                total_purged_files += n
                total_purged_bytes += b

        # Check again
        current_percent = get_disk_percent(REPO_ROOT)
        if current_percent >= TARGET_THRESHOLD:
            # Phase 3: progressively reduce WAL retention count
            for keep_n in [100, 50, 20, 10, 5]:
                if current_percent < TARGET_THRESHOLD:
                    break
                old_wal = find_old_wal(0, keep_n)  # ignore days, keep only keep_n
                if old_wal:
                    log.warning("aggressive purge: keeping only %d WAL segments", keep_n)
                    n, b = purge_files(old_wal, dry_run=dry_run)
                    total_purged_files += n
                    total_purged_bytes += b
                    current_percent = get_disk_percent(REPO_ROOT)

        # Check again
        current_percent = get_disk_percent(REPO_ROOT)
        if current_percent >= TARGET_THRESHOLD:
            # Phase 4: progressively reduce log retention
            for ret_days in [7, 3, 1, 0]:
                if current_percent < TARGET_THRESHOLD:
                    break
                old_logs = find_old_logs(ret_days)
                if old_logs:
                    log.warning("aggressive purge: log retention reduced to %d days", ret_days)
                    n, b = purge_files(old_logs, dry_run=dry_run)
                    total_purged_files += n
                    total_purged_bytes += b
                    current_percent = get_disk_percent(REPO_ROOT)

        if not dry_run:
            cleanup_empty_dirs()

        # Recompute final
        total, used, free = get_disk_usage(REPO_ROOT)
        final_percent = (used / total * 100.0) if total > 0 else 0.0
        status["final_disk_percent"] = round(final_percent, 2)
        status["purged_files"] = total_purged_files
        status["purged_bytes"] = total_purged_bytes

        log.info("purge complete: %d files, %d bytes freed. disk now %.1f%%",
                 total_purged_files, total_purged_bytes, final_percent)

        if final_percent >= ALERT_THRESHOLD:
            send_alert(final_percent,
                       f"Purge completed but disk still at {final_percent:.1f}% — manual intervention needed")
            status["action"] = "purged+alert"
        elif final_percent >= PURGE_THRESHOLD:
            log.warning("purge could not bring disk below %.1f%% (now %.1f%%)",
                        PURGE_THRESHOLD, final_percent)
            status["action"] = "purged_insufficient"
        else:
            status["action"] = "purged_ok"

    # Update state
    state = load_state()
    state["last_check"] = status["timestamp"]
    state["last_percent"] = status["disk_percent"]
    if "final_disk_percent" in status:
        state["last_final_percent"] = status["final_disk_percent"]
    state["last_purged_files"] = status["purged_files"]
    state["last_purged_bytes"] = status["purged_bytes"]
    state["last_action"] = status["action"]
    save_state(state)

    return status


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def cmd_status():
    """Print JSON status."""
    state = load_state()
    current = get_disk_percent(REPO_ROOT)
    total, used, free = get_disk_usage(REPO_ROOT)
    report = {
        "current_disk_percent": round(current, 2),
        "total_bytes": total,
        "used_bytes": used,
        "free_bytes": free,
        "purge_threshold": PURGE_THRESHOLD,
        "alert_threshold": ALERT_THRESHOLD,
        "last_check": state.get("last_check"),
        "last_percent": state.get("last_percent"),
        "last_action": state.get("last_action"),
        "last_purged_files": state.get("last_purged_files", 0),
        "last_purged_bytes": state.get("last_purged_bytes", 0),
        "log_dirs": [str(d) for d in LOG_DIRS if d.exists()],
        "wal_dirs": [str(d) for d in WAL_ARCHIVE_DIRS if d.exists()],
    }
    print(json.dumps(report, indent=2))


def cmd_daemon(dry_run: bool):
    """Continuous monitoring loop."""
    log.info("starting daemon mode (interval=%ds, dry_run=%s)", DAEMON_INTERVAL, dry_run)
    try:
        while True:
            try:
                run_watchdog(dry_run=dry_run)
            except Exception as e:
                log.error("watchdog cycle failed: %s", e, exc_info=True)
            time.sleep(DAEMON_INTERVAL)
    except KeyboardInterrupt:
        log.info("daemon stopped by user")


def main():
    parser = argparse.ArgumentParser(
        description="Runa disk-watchdog: monitor disk usage and auto-purge old logs/WAL archives"
    )
    parser.add_argument("--daemon", action="store_true",
                        help="Run in continuous daemon mode")
    parser.add_argument("--dry-run", action="store_true",
                        help="Show what would be purged without deleting")
    parser.add_argument("--status", action="store_true",
                        help="Print JSON status and exit")
    parser.add_argument("--interval", type=int, default=DAEMON_INTERVAL,
                        help=f"Daemon poll interval in seconds (default: {DAEMON_INTERVAL})")
    args = parser.parse_args()

    global DAEMON_INTERVAL
    DAEMON_INTERVAL = args.interval

    if args.status:
        cmd_status()
        return

    if args.daemon:
        cmd_daemon(dry_run=args.dry_run)
        return

    # Single run
    result = run_watchdog(dry_run=args.dry_run)
    print(json.dumps(result, indent=2, default=str))


if __name__ == "__main__":
    main()